class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        best = -1
        for i in range(n):
            total = 0
            for j in range(i, min(n, i + r)):
                total += nums[j]
                if total <= 0 and j - i + 1 >= l:
                    break
                if j - i + 1 >= l and total > 0:
                    if best == -1 or total < best:
                        best = total
        return best
